// SHA-256 inventory of the release tree.
//   node scripts/manifest.cjs          (re)write docs/RELEASE_FILE_MANIFEST.sha256
//   node scripts/manifest.cjs --check  verify the tree matches the manifest
// Excludes: .git, node_modules, the manifest itself, and the per-machine helper
// registration (helper/com.siteworks.helper.json, generated by the installer).
// Line endings are fixed by .gitattributes, so hashes are identical on every OS.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const root = path.resolve(__dirname, '..');
const manifestRel = 'docs/RELEASE_FILE_MANIFEST.sha256';
const skipDirs = new Set(['.git', 'node_modules']);
const skipFiles = new Set([manifestRel, 'helper/com.siteworks.helper.json']);

function walk(dir, out) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, e.name);
    const rel = path.relative(root, full).split(path.sep).join('/');
    if (e.isDirectory()) { if (!skipDirs.has(e.name)) walk(full, out); }
    else if (e.isFile() && !skipFiles.has(rel)) out.push(rel);
  }
  return out;
}
const hash = (rel) => crypto.createHash('sha256').update(fs.readFileSync(path.join(root, rel))).digest('hex');
const files = walk(root, []).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
const lines = files.map((f) => `${hash(f)}  ${f}`);
const target = path.join(root, manifestRel);

if (process.argv.includes('--check')) {
  const want = new Map(fs.readFileSync(target, 'utf8').split(/\r?\n/).filter(Boolean)
    .map((l) => { const m = /^([0-9a-f]{64}) {2}(.+)$/.exec(l); return m ? [m[2], m[1]] : [l, null]; }));
  const problems = [];
  for (const f of files) { if (!want.has(f)) problems.push(`not in manifest: ${f}`); else if (want.get(f) !== hash(f)) problems.push(`hash mismatch: ${f}`); }
  for (const f of want.keys()) if (!files.includes(f)) problems.push(`listed but missing: ${f}`);
  if (problems.length) { console.error(problems.join('\n') + '\nRun: npm run manifest'); process.exit(1); }
  console.log(`Manifest OK: ${files.length} files verified.`);
} else {
  fs.writeFileSync(target, lines.join('\n') + '\n');
  console.log(`Wrote ${manifestRel} (${files.length} files).`);
}
